"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[27845],{63700:e=>{e.exports=JSON.parse('{"id":"2026-10-21-sms-mms-media-urls","date":"2026-10-21","products":["Connect","APIs"],"product":"Connect","channel":"SMS","changeType":"Added","title":"MMS media support on the Send SMS API","excerpt":"You can now send media (image, audio, video, etc.) along with an SMS as an MMS, by adding a mediaUrls field to your send request \u2014 up to 10 HTTPS URLs, each up to 4096 characters. MMS is currently supported for US/Canada destinations only; for other destinations mediaUrls is ignored and the message is sent as a plain S\u2026","hasArticle":true,"bodyHtml":"<p>You can now send media (image, audio, video, etc.) along with an SMS as an MMS, by adding a <code>mediaUrls</code> field to your send request \u2014 up to 10 HTTPS URLs, each up to 4096 characters. MMS is currently supported for US/Canada destinations only; for other destinations <code>mediaUrls</code> is ignored and the message is sent as a plain SMS.</p>\\n<p>The delivery receipt&#39;s <code>outboundContent</code> object also now includes the <code>mediaUrls</code> that were sent, alongside the existing text body.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/docs/send-sms-api-reference\\">Send SMS API</a></li>\\n<li><a href=\\"/connect/reference/send-sms-single\\">Send SMS</a></li>\\n<li><a href=\\"/connect/docs/delivery-receipts-for-outbound-sms\\">Delivery receipts for outbound SMS</a></li>\\n</ul>\\n"}')}}]);